//! Cache storage implementation.
//!
//! All writes use atomic rename to prevent corruption when multiple
//! tool installations run concurrently. Content is always written
//! before metadata so that a reader never sees metadata pointing to
//! a missing or partially-written content file.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

use super::entry::CacheEntry;

/// Counter for generating unique temp file names within this process.
static TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

impl CacheStore {
    /// Create a new cache store.
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// Get the cache root directory.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Ensure the cache directory exists.
    fn ensure_dir(&self) -> Result<()> {
        fs::create_dir_all(&self.root)
            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
    }

    /// Get the path for storing an entry's content.
    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        let key = format!("{}:{}", source_id, template_name);
        let hash = Sha256::digest(key.as_bytes());
        let hash_str = hex::encode(&hash[..16]);
        self.root.join(hash_str)
    }

    /// Get the metadata file path for an entry.
    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        self.content_path(source_id, template_name)
            .with_extension("meta.json")
    }

    /// Write data to a file atomically by writing to a temporary file
    /// in the same directory then renaming. Rename is atomic on the
    /// same filesystem, so concurrent readers always see either the
    /// old complete file or the new complete file.
    fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
        let tmp_path = path.with_extension(format!(
            "tmp.{}",
            std::process::id()
        ));
        fs::write(&tmp_path, data)
            .with_context(|| format!("Failed to write temp file {:?}", tmp_path))?;
        fs::rename(&tmp_path, path).with_context(|| {
            // Clean up the temp file on rename failure
            let _ = fs::remove_file(&tmp_path);
            format!("Failed to rename {:?} to {:?}", tmp_path, path)
        })?;
        Ok(())
    }

    /// Store content and return a cache entry.
    pub fn store(
        &self,
        source_id: &str,
        template_name: &str,
        content: &str,
        ttl_seconds: u64,
    ) -> Result<CacheEntry> {
        self.ensure_dir()?;

        let content_path = self.content_path(source_id, template_name);

        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
            .with_size(content.len() as u64);

        // Write content first, then metadata. A reader that sees
        // metadata will always find the content file present.
        Self::atomic_write(&content_path, content.as_bytes())?;
        self.save_metadata(&entry)?;

        Ok(entry)
    }

    /// Load a cached entry's metadata.
    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
        let meta_path = self.metadata_path(source_id, template_name);

        if !meta_path.exists() {
            return Ok(None);
        }

        let json = match fs::read_to_string(&meta_path) {
            Ok(j) => j,
            // File may have been removed between the exists check and
            // the read (concurrent remove), treat as a cache miss.
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(e) => return Err(e.into()),
        };

        let entry: CacheEntry = match serde_json::from_str(&json) {
            Ok(e) => e,
            // Corrupted metadata — treat as a cache miss.
            Err(_) => return Ok(None),
        };

        // Verify the content file exists; if it's missing, the cache
        // entry is incomplete (e.g., metadata written from a previous
        // run whose content was cleaned up).
        if !entry.content_path.exists() {
            return Ok(None);
        }

        Ok(Some(entry))
    }

    /// Read the cached content.
    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
        fs::read_to_string(&entry.content_path).with_context(|| {
            format!(
                "Failed to read cached content from {:?}",
                entry.content_path
            )
        })
    }

    /// Save entry metadata atomically.
    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
        let json = serde_json::to_string_pretty(entry)?;
        Self::atomic_write(&meta_path, json.as_bytes())
    }

    /// Update an entry's metadata (e.g., after revalidation).
    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
        self.save_metadata(entry)
    }

    /// Remove a cached entry.
    ///
    /// Metadata is removed first so that concurrent readers see a
    /// cache miss rather than metadata pointing to a missing file.
    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
        let content_path = self.content_path(source_id, template_name);
        let meta_path = self.metadata_path(source_id, template_name);

        let mut removed = false;

        // Remove metadata first — this makes the entry invisible to
        // concurrent readers immediately.
        if meta_path.exists() {
            fs::remove_file(&meta_path)?;
            removed = true;
        }

        if content_path.exists() {
            fs::remove_file(&content_path)?;
            removed = true;
        }

        Ok(removed)
    }

    /// List all cached entries.
    pub fn list(&self) -> Result<Vec<CacheEntry>> {
        self.ensure_dir()?;

        let mut entries = Vec::new();

        for entry in fs::read_dir(&self.root)? {
            let entry = entry?;
            let path = entry.path();

            if path.extension().is_some_and(|e| e == "json") {
                if let Ok(json) = fs::read_to_string(&path) {
                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
                        entries.push(cache_entry);
                    }
                }
            }
        }

        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
        Ok(entries)
    }

    /// Clear all cached entries.
    pub fn clear(&self) -> Result<usize> {
        let entries = self.list()?;
        let count = entries.len();

        for entry in entries {
            let _ = self.remove(&entry.source_id, &entry.template_name);
        }

        Ok(count)
    }

    /// Get total cache size in bytes.
    pub fn total_size(&self) -> Result<u64> {
        let entries = self.list()?;
        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
    }
}

